import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"ADR-087 — Kernel \\"systems\\" layer: separating guidance/control controllers from physics engines","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-087.md","filePath":"adr/ADR-087.md"}'),a={name:"adr/ADR-087.md"};function r(c,e,i,l,d,h){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="adr-087-—-kernel-systems-layer-separating-guidance-control-controllers-from-physics-engines" tabindex="-1">ADR-087 — Kernel &quot;systems&quot; layer: separating guidance/control controllers from physics engines <a class="header-anchor" href="#adr-087-—-kernel-systems-layer-separating-guidance-control-controllers-from-physics-engines" aria-label="Permalink to &quot;ADR-087 — Kernel &quot;systems&quot; layer: separating guidance/control controllers from physics engines&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-08-31 · Operator-directed (Physics Lab spaceflight program) · builds on RFC-034 (ascent physics / PEG) · enables the Lab &quot;Systems&quot; lesson family (tasks #28–#30)</p></blockquote><p><strong>Gating sentence.</strong> The pure physics kernel (<code>src/lib/physics/</code>) gains a <strong><code>systems/</code> sub-layer</strong> for the guidance/control <strong>controllers</strong> a real vehicle runs — the algorithms that <em>steer</em> the physics, as distinct from the physics <em>engines</em> they steer. The first extraction moves <strong>Powered Explicit Guidance</strong> (<code>PEG</code>, <code>pegSolve</code>, <code>pegPitchRad</code>, <code>timeToApoapsisS</code>, <code>PegState</code>) out of <code>ascent/ascent-physics.ts</code> into <code>systems/peg.ts</code> <strong>unchanged</strong> (byte-identical logic; ascent-physics re-exports for back-compat, so every importer and all 170 ascent tests stay green). Powered-descent guidance and re-entry lift-vector steering join <code>systems/</code> as new controllers in later slices.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The physics kernel had grown one real closed-loop <strong>controller</strong> — PEG, the ascent insertion guidance that solves a two-point boundary problem each major cycle so a low-TWR upper stage reaches <code>(r=rT, vr=0)</code> at circular speed — buried inside <code>ascent-physics.ts</code> next to the atmosphere/gravity/thrust <strong>physics</strong>. The operator&#39;s framing of the Physics Lab spaceflight program draws a three-layer picture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  KERNEL SCIENCE (physics engines)   mechanics · transfer · ephemeris · ascent/descent integrators</span></span>
<span class="line"><span>  KERNEL SYSTEMS (controllers)       PEG · powered-descent guidance · entry lift-steering</span></span>
<span class="line"><span>  LAB INTEGRATION                    formulas + figures + goals that expose both, and put it together</span></span></code></pre></div><p>The distinction is real and pedagogically load-bearing: a &quot;Systems&quot; lesson family teaches <em>how a machine flies the physics</em> (the guidance computer solving its own path in real time) — a different question from &quot;what is the physics.&quot; To teach and <strong>black-box-simulate</strong> a controller in isolation, it must be a first-class, pure, self-contained module — not an implementation detail of an integrator.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>A <code>systems/</code> layer under the pure kernel.</strong> <code>src/lib/physics/systems/*.ts</code> holds guidance/control controllers. Same purity contract as the rest of <code>physics/**</code> (framework-free; only <code>$types/*</code>, <code>$data/*</code>, and intra-kernel <code>$lib/physics/*</code> imports). A controller is:</p><ul><li><strong>Pure</strong> — a function of state → command; no trajectory integration, no side effects.</li><li><strong>Black-box-simulatable</strong> — callable standalone (a Lab formula can drive <code>pegSolve</code> on a synthetic state to show what it commands), not only reachable through the flight integrator.</li><li><strong>Honesty-preserving</strong> — a controller only <em>steers</em>; the physics engine still decides truth (PEG&#39;s steering can never fabricate an orbit — <code>integrateAscent</code>&#39;s osculating-perigee gate decides SECO/<code>reachedOrbit</code>).</li></ul><p><strong>First move — PEG.</strong> <code>systems/peg.ts</code> receives <code>PEG</code>, <code>pegSolve</code>, <code>pegPitchRad</code>, <code>timeToApoapsisS</code>, <code>PegState</code> verbatim, importing only <code>MU_EARTH_M3_S2</code> (its sole external dependency — no circular import with <code>ascent-physics.ts</code>). <code>ascent-physics.ts</code> imports them for <code>integrateAscent</code>&#39;s internal use and <strong>re-exports</strong> them, so <code>peg-guidance.test.ts</code> and <code>ascent/index.ts</code> resolve them unchanged.</p><p><strong>Next controllers (later slices, task #30).</strong> <code>systems/powered-descent.ts</code> (throttle/retarget landing guidance — currently only implicit inside <code>descent-physics.ts</code>) and <code>systems/entry-steering.ts</code> (bank-angle lift-vector steering — the descent integrator models lift physics via <code>liftToDragRatio</code> but has no steering controller; this also reconciles the ballistic <code>entry-corridor</code> formula with the lift the integrator already has).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>No behaviour change.</strong> The extraction is mechanical; <code>integrateAscent</code> produces byte-identical results (170 ascent tests green, incl. <code>peg-guidance.test.ts</code>).</li><li><strong>Enables the Systems lesson family</strong> — each controller can be surfaced as a Lab formula/simulation that runs it in isolation (open-loop pitch table vs closed-loop PEG takeover; a suicide-burn solver; lift steering through the entry corridor).</li><li><strong>A clean seam for the &quot;put it together&quot; layer</strong> — mission-plan goals compose physics engines + systems controllers end-to-end.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li>Not rewriting or re-tuning PEG — verbatim move only.</li><li>Not moving <em>physics helpers</em> (gravity, circular speed, atmosphere) — those stay in the engines. <code>timeToApoapsisS</code> moves with PEG only because it is the guidance relight rule&#39;s Kepler helper and travels with the controller its callers import together.</li></ul>`,16)])])}const u=t(a,[["render",r]]);export{g as __pageData,u as default};
